//! Source-bound static and two-stage capital comparison over shared scenarios (BD-229).
//! Determinism: Exact (bounded model input and checked rational portfolio calculations).

use std::path::Path;

use fmine_core::anchor::SourceAnchor;
use fmine_evidence::Refusal;

use crate::{Envelope, NextAction, worksheet_input};

mod executive;
mod investment;

pub(crate) use executive::ExecutiveSnapshot;

pub(crate) fn executive_snapshot(
    text: &str,
    source: &SourceAnchor,
    root: &Path,
    action: &str,
) -> Result<Option<ExecutiveSnapshot>, Refusal> {
    use fmine_registry::toml_subset::{TomlValue, parse_subset};
    let Ok(doc) = parse_subset(text) else {
        return Ok(None);
    };
    if !matches!(doc.top_get("schema").map(|f| &f.value), Some(TomlValue::Str(s)) if s == executive::SCHEMA)
    {
        return Ok(None);
    }
    executive::journal_snapshot(&doc, text, source, root, action).map(Some)
}

